# Not in the book: the newest upstream release, built with cargo as its
# release script (bin/package) builds it. Upstream publishes no checksum
# for the source archive.
build() {
    # Keep cargo's registry and download cache inside the build directory
    # rather than in root's home in the shared build root.
    export CARGO_HOME="$PWD/.cargo-home"
    # --locked: build exactly the crate versions in upstream's Cargo.lock.
    cargo build --release --locked --bin just

    # The manual page and shell completions, generated by just itself as
    # upstream's release workflow and justfile do.
    local just=target/release/just shell
    "$just" --man > just.1
    for shell in bash zsh fish; do
        "$just" --completions "$shell" > "just.$shell"
    done
}

package() {
    install -Dm755 target/release/just "$DESTDIR/usr/bin/just"
    install -Dm644 just.1 "$DESTDIR/usr/share/man/man1/just.1"
    install -Dm644 just.bash "$DESTDIR/usr/share/bash-completion/completions/just"
    install -Dm644 just.zsh "$DESTDIR/usr/share/zsh/site-functions/_just"
    install -Dm644 just.fish "$DESTDIR/usr/share/fish/vendor_completions.d/just.fish"
}
